export function BattleCard(a,s,n){const e=s[a.era]||{label:a.era,color:"#888"};return`\n        <div class="battle-card" data-era="${a.era}" data-index="${n}">\n            <div class="battle-card-header" style="border-left: 4px solid ${e.color}">\n                <span class="battle-era-badge" style="background: ${e.color}20; color: ${e.color}">${e.label}</span>\n                <span class="battle-date">${a.date}</span>\n            </div>\n            <h3 class="battle-name">${a.name}</h3>\n            <p class="battle-location">${a.location}</p>\n            <p class="battle-summary">${a.summary.substring(0,180)}...</p>\n            <div class="battle-combatants-mini">\n                <div class="cb-side">\n                    <span class="cb-label">Led by</span>\n                    <span class="cb-name">${a.combatants.side1.leader}</span>\n                </div>\n                <span class="cb-vs">vs</span>\n                <div class="cb-side">\n                    <span class="cb-label">Led by</span>\n                    <span class="cb-name">${a.combatants.side2.leader}</span>\n                </div>\n            </div>\n            <button class="battle-expand-btn" data-index="${n}" aria-expanded="false">\n                <span>Full Battle Details</span>\n                <svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="4 6 8 10 12 6"></polyline></svg>\n            </button>\n        </div>\n    `}export function BattleDetail(a){const s=a.keyEvents.map(a=>`<li>${a}</li>`).join("");return`\n        <div class="battle-detail-content">\n            <div class="detail-forces">\n                <div class="force-card">\n                    <h4 style="color: ${a.color}">${a.combatants.side1.name}</h4>\n                    <div class="force-info">\n                        <span class="fi-label">Commander</span>\n                        <span class="fi-value">${a.combatants.side1.leader}</span>\n                    </div>\n                    <div class="force-info">\n                        <span class="fi-label">Forces</span>\n                        <span class="fi-value">${a.combatants.side1.forces}</span>\n                    </div>\n                </div>\n                <div class="force-vs">\n                    <span>VS</span>\n                </div>\n                <div class="force-card">\n                    <h4>${a.combatants.side2.name}</h4>\n                    <div class="force-info">\n                        <span class="fi-label">Commander</span>\n                        <span class="fi-value">${a.combatants.side2.leader}</span>\n                    </div>\n                    <div class="force-info">\n                        <span class="fi-label">Forces</span>\n                        <span class="fi-value">${a.combatants.side2.forces}</span>\n                    </div>\n                </div>\n            </div>\n\n            <div class="battle-detail-section">\n                <h4>Outcome</h4>\n                <p class="outcome-text">${a.outcome}</p>\n            </div>\n\n            <div class="battle-detail-section">\n                <h4>Casualties</h4>\n                <div class="casualties-grid">\n                    <div class="casualty-box">\n                        <span class="cb-label">${a.combatants.side1.name}</span>\n                        <span class="cb-value">${a.casualties.side1}</span>\n                    </div>\n                    <div class="casualty-box">\n                        <span class="cb-label">${a.combatants.side2.name}</span>\n                        <span class="cb-value">${a.casualties.side2}</span>\n                    </div>\n                </div>\n            </div>\n\n            <div class="battle-detail-section">\n                <h4>Key Events</h4>\n                <ol class="events-list">${s}</ol>\n            </div>\n\n            <div class="battle-detail-section">\n                <h4>Tactics & Strategy</h4>\n                <p>${a.tactics}</p>\n            </div>\n\n            <div class="battle-detail-section">\n                <h4>Historical Impact</h4>\n                <p>${a.impact}</p>\n            </div>\n\n            <div class="battle-significance">\n                <h4>Why It Matters</h4>\n                <p>${a.significance}</p>\n            </div>\n        </div>\n    `}